import sys
def main():
    lines = sys.stdin.read().splitlines()
    if not lines: return
    for line in lines:
        parts = line.split()
        if parts:
            try:
                nums = [int(p) for p in parts]
                print(sum(nums))
            except:
                print(' '.join(parts))
if __name__ == '__main__': main()

